import { NextResponse } from 'next/server';
import { TransactionFactory } from '@/lib/factories/transaction.factory';
import { withAuth } from '@/lib/auth';
import { PrismaClient } from "@prisma/client";
import { NextApiRequest, NextApiResponse } from "next";

const prisma = new PrismaClient();
const transactionFactory = new TransactionFactory(prisma);

async function handler(req: NextApiRequest, res: NextApiResponse, userId: string) {
  try {
    const body = req.body;
    
    const transactionData = await transactionFactory.createTransaction({
      ...body,
      userId
    });

    const transaction = await prisma.transaction.create({
      data: {
        name: transactionData.name,
        type: transactionData.type,
        amountCAD: transactionData.amount_cad,
        amountUSD: transactionData.amount_usd,
        date: transactionData.date,
        notes: transactionData.notes,
        userId: transactionData.userId,
        monthId: transactionData.monthId,
        categoryId: 1 // Update with actual category logic
      }
    });

    console.log(transaction);

    return res.status(200).json(transaction);
  } catch (error) {
    console.error('Transaction creation error:', error);
    return res.status(400).json({ error: error instanceof Error ? error.message : 'Failed to create transaction' });
  }
}

export default withAuth(handler);

